package io.xeros.solo;
import io.xeros.*;import io.xeros.content.questing.*;import io.xeros.content.dialogue.*;import io.xeros.model.collisionmap.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.entity.npc.*;import io.xeros.model.items.*;import java.util.*;
public class ClassicQuests70Check {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){Player p=BossRoutesCheck.actor();p.setLoginName("classic70qa");p.setDisplayName("Classic70qa");Arrays.fill(p.playerItems,0);Arrays.fill(p.playerItemsN,0);return p;}
 static Quest quest(Player p,String name){return p.getQuesting().getQuestList().stream().filter(q->q.getName().equals(name)).findFirst().orElseThrow();}
 static NPC npc(int id,int x,int y,int h){return Arrays.stream(NPCHandler.npcs).filter(n->n!=null&&n.getNpcId()==id&&n.getX()==x&&n.getY()==y&&n.getHeight()==h).findFirst().orElseThrow(()->new AssertionError("Missing world NPC "+id));}
 static void at(Player p,int x,int y,int h){BossRoutesCheck.at(p,x,y,h);}static void give(Player p,int id,int amount){p.getItems().addItem(id,amount);}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}
 static DialogueObject offer(Player p,NPC n){at(p,n.getX(),n.getY()+1,n.getHeight());ok(p.getQuesting().handleNpcClick(n,1),"Native quest NPC dispatch "+n.getNpcId());DialogueBuilder d=p.getDialogueBuilder();ok(d!=null,"Missing dialogue stage="+quest(p,"Cook's Assistant").getStage()+" hp="+p.getHealth().getCurrentHealth()+" dead="+p.isDead+" disc="+p.isDisconnected()+" pin="+p.getBankPin().requiresUnlock()+" locked="+p.getLock().cannotInteract(p)+" inst="+p.getInstance()+" npcinst="+n.getInstance()+" npcheight="+n.getHeight()+" playerheight="+p.getHeight()+" d="+p.getPosition().withinDistance(n.getPosition(),3));d.sendNextDialogue();return d.getCurrent();}
 static void accept(Player p,NPC n){DialogueObject d=offer(p,n);ok(d!=null,"Missing option");d.handleAction(p,DialogueAction.OPTION_1);}
 static WorldObject object(Player p,int id,int x,int y,int h){at(p,x,y+1,h);return p.getRegionProvider().get(x,y).getWorldObject(id,x,y,h).orElseThrow(()->new AssertionError("Missing map object "+id+" at "+x+","+y));}
 static void click(Player p,int id,int x,int y,int h,int opt){ok(p.getQuesting().handleObjectClick(object(p,id,x,y,h),opt),"Object handler "+id);}
 static void tick(int n){SkillsAuditCheck.tick(n);}
 static void reload(Player p)throws Exception{ok(PlayerSave.saveGameInstant(p),"Real save failed");Player q=actor();ok(PlayerSave.loadGame(q,"classic70qa","IsolatedAudit",true).toString().equals("SUCCESS"),"Real reload failed");for(Quest a:p.getQuesting().getQuestList())ok(quest(q,a.getName()).getStage()==a.getStage(),"Stage save "+a.getName());ok(q.getQuesting().resources().encode().equals(p.getQuesting().resources().encode()),"Resource save");ok(Arrays.equals(p.playerItems,q.playerItems)&&Arrays.equals(p.playerItemsN,q.playerItemsN),"Inventory reload");SkillsAuditCheck.clear(q);PlayerHandler.players[1]=p;}
 static void cook()throws Exception{Player p=actor();Quest q=quest(p,"Cook's Assistant");NPC n=npc(4626,3209,3215,0);DialogueObject stale=offer(p,n);at(p,3100,3500,0);stale.handleAction(p,DialogueAction.OPTION_1);ok(q.getStage()==0,"Remote dialogue start");accept(p,n);stale.handleAction(p,DialogueAction.OPTION_1);ok(q.getStage()==1,"Replayed start");p.getQuesting().processClassic();for(int[] a:new int[][]{{1931,3209,3214},{1925,3211,3211}}){GroundItem item=Server.itemHandler.getGroundItem(p,a[0],a[1],a[2],0);ok(item!=null,"World supply "+a[0]);Server.itemHandler.removeGroundItem(p,item,true);}click(p,8689,3172,3317,0,1);tick(4);ok(count(p,1927)==1,"Milking");at(p,3177,3296,0);p.getQuesting().processClassic();GroundItem egg=Server.itemHandler.getGroundItem(p,1944,3177,3296,0);ok(egg!=null,"Egg world spawn");Server.itemHandler.removeGroundItem(p,egg,true);accept(p,n);ok(q.getStage()==4,"Partial egg and milk hand-in "+q.getStage());reload(p);click(p,15506,3158,3299,0,1);tick(3);ok(count(p,1947)==1,"Wheat harvest");at(p,3165,3307,2);ok(p.getQuesting().handleItemOnObject(1947,24961,3166,3307),"Fill hopper");ok(count(p,1947)==0,"Hopper did not consume Grain");reload(p);click(p,24964,3166,3305,2,1);reload(p);click(p,1781,3166,3306,0,1);ok(count(p,1933)==1,"Mill flour collection");int xp=p.playerXP[7];accept(p,n);ok(q.isQuestCompleted()&&p.playerXP[7]==xp+300&&p.getQuesting().getQuestPoints()==1,"Cook rewards");q.giveQuestCompletionRewards();ok(p.playerXP[7]==xp+300,"Duplicate Cook XP");reload(p);System.out.println("COOK_FULL_WORLD_GATHER_PARTIAL_HANDINS_MILL_STAGE_SAVES_STALE_DIALOGUE_AND_EXACT_REWARD_PASS");SkillsAuditCheck.clear(p);}
 static void sheep()throws Exception{Player p=actor();Quest q=quest(p,"Sheep Shearer");NPC fred=npc(732,3190,3273,0);accept(p,fred);ok(q.getStage()==1&&count(p,1735)==1,"Fred start and shears");NPC sheep=npc(2693,3195,3270,0);at(p,3195,3271,0);p.getQuesting().handleNpcClick(sheep,1);tick(3);ok(count(p,1737)==1&&sheep.getNpcId()==2691,"Native shearing");p.getQuesting().handleNpcClick(sheep,1);tick(3);ok(count(p,1737)==1,"Shearing regrowth guard");WorldObject wheel=p.getRegionProvider().get(3209,3213).worldObjectsSnapshot().stream().filter(o->o.id==14889&&o.height==1).findFirst().orElseThrow();at(p,wheel.x,wheel.y+1,1);p.getQuesting().handleItemOnObject(1737,14889,wheel.x,wheel.y);tick(3);ok(count(p,1759)==1&&count(p,1737)==0,"Wool spinning");accept(p,fred);ok(q.getStage()==2,"Partial wool delivery");reload(p);give(p,1759,19);int xp=p.playerXP[12];accept(p,fred);ok(q.isQuestCompleted()&&count(p,995)==60&&p.playerXP[12]==xp+150,"Sheep final rewards");q.giveQuestCompletionRewards();ok(count(p,995)==60&&p.playerXP[12]==xp+150,"Repeat Sheep reward");reload(p);System.out.println("SHEEP_FULL_WORLD_SHEAR_SPIN_PARTIAL_DELIVERY_EXACT_XP_COINS_AND_SAVE_PASS");SkillsAuditCheck.clear(p);}
 static void rune()throws Exception{Player p=actor();Quest q=quest(p,"Rune Mysteries");NPC duke=npc(815,3210,3221,1),sed=npc(5034,3101,9570,0),aub=npc(2886,3253,3401,0);accept(p,duke);ok(q.getStage()==1&&count(p,1438)==1,"Duke talisman");reload(p);accept(p,sed);ok(q.getStage()==2&&count(p,1438)==0&&count(p,290)==1,"Research package");reload(p);p.getItems().deleteItem2(290,1);accept(p,sed);ok(count(p,290)==1&&q.getStage()==2,"Package replacement");accept(p,aub);ok(q.getStage()==3&&count(p,290)==0,"Aubury research delivery");reload(p);accept(p,aub);ok(q.getStage()==4&&count(p,291)==1,"Aubury notes");reload(p);p.getItems().deleteItem2(291,1);accept(p,aub);ok(count(p,291)==1,"Notes replacement");accept(p,sed);ok(q.isQuestCompleted()&&count(p,291)==0&&count(p,1438)==1,"Rune completion and talisman returned");reload(p);at(p,sed.getX(),sed.getY()+1,0);p.getQuesting().handleNpcClick(sed,2);ok(p.teleTimer>0&&p.teleX==2929&&p.teleY==4813,"Essence mine unlock");p.teleTimer=0;System.out.println("RUNE_FULL_TALISMAN_PACKAGE_AUBURY_NOTES_REPLACEMENTS_MINE_UNLOCK_AND_STAGE_RELOADS_PASS");SkillsAuditCheck.clear(p);}
 static void ghost()throws Exception{Player p=actor();Quest q=quest(p,"The Restless Ghost");NPC a=npc(921,3243,3208,0),u=npc(923,3145,3175,0);accept(p,a);reload(p);accept(p,u);ok(q.getStage()==2&&count(p,552)==1,"Ghostspeak amulet");reload(p);click(p,2145,3249,3192,0,1);NPC ghost=Arrays.stream(NPCHandler.npcs).filter(n->n!=null&&n.getNpcId()==922).findFirst().orElseThrow();at(p,3250,3194,0);p.getQuesting().handleNpcClick(ghost,1);ok(q.getStage()==2,"Understanding without worn amulet");p.playerEquipment[Player.playerAmulet]=552;accept(p,ghost);ok(q.getStage()==3,"Ghost skull request");reload(p);click(p,2146,3120,9566,0,1);ok(q.getStage()==4&&count(p,553)==1,"Altar skull");ok(Arrays.stream(NPCHandler.npcs).anyMatch(n->n!=null&&n.getNpcId()==70&&n.getY()==9566),"Missing optional skeleton");reload(p);at(p,3250,3192,0);ok(p.getQuesting().handleItemOnObject(553,2145,3249,3192),"Skull on coffin native dispatch");ok(q.isQuestCompleted(),"Open coffin retained in this session");int xp=p.playerXP[5];q.giveQuestCompletionRewards();ok(p.playerXP[5]==xp,"Repeated prayer reward");tick(9);reload(p);System.out.println("GHOST_FULL_AERECK_URHNEY_WORN_AMULET_GHOST_ALTAR_SKELETON_COFFIN_PRAYER_AND_SAVE_PASS");p.getQuesting().logoutClassic();SkillsAuditCheck.clear(p);}
 public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();cook();sheep();rune();ghost();System.out.println("CLASSIC_QUESTS70_ALL_PASS");System.exit(0);}
}